def patch(path, pairs):
    h = io.open(path, encoding='utf-8').read()
    before = h
    done = skipped = 0
    for old, new in pairs:
        assert old not in new, 'новая строка не должна содержать старую: %s' % old[:50]
        if old not in h and old.endswith('.'):
            # на собранных страницах точка в конце абзаца снята модулем чистки,
            # поэтому там текст лежит без неё
            old, new = old[:-1], new[:-1] if new.endswith('.') else new
        if old not in h:
            skipped += 1
            continue
        h = h.replace(old, new)
        done += 1
    if h != before:
        io.open(path, 'w', encoding='utf-8').write(h)
    print('%s: заменено %d, уже было %d' % (path, done, skipped))


def main():
    patch('keysy/cases-data.js', PAIRS_RU)
    patch('en/keysy/cases-data.js', PAIRS_EN)
    for f in sorted(glob.glob('keysy/*.html')) + ['keysy.html']:
        patch(f, PAIRS_RU)
    for f in sorted(glob.glob('en/keysy/*.html')) + ['en/keysy.html']:
        patch(f, PAIRS_EN)


if __name__ == '__main__':
    main()
